function OnboardingModal({ onClose }) {
  const [step, setStep] = useState(0);
  const slide = ONBOARDING_SLIDES[step];
  const isLast = step === ONBOARDING_SLIDES.length - 1;
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(20,30,35,0.55)", zIndex: 999, display: "flex", alignItems: "center", justifyContent: "center", padding: 18 }}>
      <div style={{ background: "#fff", borderRadius: 20, padding: "24px 20px 20px", maxWidth: 360, width: "100%", textAlign: "center", boxShadow: "0 20px 50px rgba(0,0,0,0.25)" }}>
        <div style={{ fontSize: 40, marginBottom: 10 }}>{slide.icon}</div>
        <h3 style={{ fontSize: 15.5, fontWeight: 800, color: "#1F2D3D", margin: "0 0 10px" }}>{slide.title}</h3>
        <p style={{ fontSize: 12.5, color: "#5A7080", lineHeight: 2, margin: "0 0 20px" }}>{slide.body}</p>
        <div style={{ display: "flex", justifyContent: "center", gap: 5, marginBottom: 18 }}>
          {ONBOARDING_SLIDES.map((_, i) => (
            <div key={i} style={{ width: i === step ? 18 : 6, height: 6, borderRadius: 999, background: i === step ? "#17383D" : "#DCE8F0", transition: "all 0.2s" }} />
          ))}
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          {step > 0 && (
            <button onClick={() => setStep(step - 1)}
              style={{ flex: 1, padding: "11px", borderRadius: 12, border: "1px solid #DCE8F0", background: "#fff", color: "#5A7080", fontWeight: 700, fontSize: 12.5, cursor: "pointer" }}>
              قبلی
            </button>
          )}
          <button onClick={() => (isLast ? onClose() : setStep(step + 1))}
            style={{ flex: 2, padding: "11px", borderRadius: 12, border: "none", background: "linear-gradient(160deg, #2C5560, #17383D 55%, #0E2529)", color: "#fff", fontWeight: 700, boxShadow: "0 8px 16px rgba(23,56,61,0.35), inset 0 1.5px 0 rgba(255,255,255,0.25), inset 0 -2px 4px rgba(0,0,0,0.2)", transition: "transform 0.15s ease", fontSize: 12.5, cursor: "pointer" }}>
            {isLast ? "شروع کنیم ←" : "بعدی"}
          </button>
        </div>
        {!isLast && (
          <button onClick={onClose} style={{ border: "none", background: "none", color: "#B0BEC5", fontSize: 11, cursor: "pointer", marginTop: 12, padding: 0 }}>
            ردکردنِ معرفی
          </button>
        )}
      </div>
    </div>
  );
}

const SLIP_STRATEGIES = [
  "هر هفته حداقل یک گفت‌وگویِ عمیق و بدونِ گوشی با همسرتان داشته باشید.",
  "هر رابطه/دوستیِ جدید را همان روزِ اول با همسرتان در میان بگذارید.",
  "رمزِ گوشی/شبکه‌هایِ اجتماعی‌تان را از همسرتان پنهان نکنید.",
  "وقتی حسِ فاصله می‌کنید، به‌جایِ فرار، مستقیم به همسرتان بگویید.",
  "از موقعیت‌هایِ تنهاییِ طولانی با یک فردِ خاص، آگاهانه پرهیز کنید.",
  "مصرفِ الکل در موقعیت‌هایِ اجتماعیِ پرخطر را محدود کنید.",
  "هر توجیهی که برایِ رفتارِ پنهانی می‌سازید را با صدایِ بلند برایِ خودتان بازخوانی کنید.",
  "نیازهایِ عاطفی/جنسیِ برآورده‌نشده را مستقیم، نه از طریقِ فردِ سوم، مطرح کنید.",
  "یک برنامه‌ی هفتگیِ مشترک (حتی کوتاه) برایِ تقویتِ صمیمیت بگذارید.",
  "اگر متوجهِ الگویِ تکرارشونده‌ای در خودتان شدید، همان لحظه با یک متخصص مشورت کنید.",
];

function SessionAudioPlayer({ sessionKey }) {
  const [audioUrl, setAudioUrl] = useState(null);
  useEffect(() => {
    if (!sessionKey) return;
    fetchWithTimeout(`/api/audio?sessionId=${encodeURIComponent(sessionKey)}`)
      .then((r) => r.json())
      .then((d) => { if (d.ok) setAudioUrl(d.url); })
      .catch(() => {});
  }, [sessionKey]);
  if (!audioUrl) return null;
  return (
    <div style={{ background: "#F5EAD0", borderRadius: 12, padding: "10px 12px", marginBottom: 14 }}>
      <p style={{ fontSize: 11.5, fontWeight: 700, color: "#7A5B2E", margin: "0 0 6px" }}>🎧 نسخه‌ی صوتیِ این جلسه</p>
      <audio controls src={audioUrl} style={{ width: "100%" }} />
    </div>
  );
}

function SlipPreventionScreen({ onBack, userEmail, userToken }) {
  const storageKey = `slip_rounds_${userEmail || "anon"}`;
  const [rounds, setRounds] = useState(() => {
    try { return JSON.parse(localStorage.getItem(storageKey)) || []; } catch (e) { return []; }
  });
  const [active, setActive] = useState(false);
  const [themeIdx, setThemeIdx] = useState(0);
  const [expandedTechniques, setExpandedTechniques] = useState({});
  const [showTechniqueLibrary, setShowTechniqueLibrary] = useState(false);
  const [stage, setStage] = useState("root"); // "root" | "dynamic"
  const [dynamicItem, setDynamicItem] = useState(null); // { q, options }
  const [roundAnswers, setRoundAnswers] = useState({});
  const [lastResult, setLastResult] = useState(null);
  const THEMES_PER_ROUND = 6;

  const roundNum = rounds.length;
  const themesForRound = Array.from({ length: THEMES_PER_ROUND }, (_, i) => SLIP_THEMES[(roundNum * THEMES_PER_ROUND + i) % SLIP_THEMES.length]);
  const theme = themesForRound[themeIdx];

  function persistRounds(next) {
    setRounds(next);
    try { localStorage.setItem(storageKey, JSON.stringify(next)); } catch (e) {}
    if (userToken) {
      fetchWithTimeout("/api/safety-plan", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ token: userToken, planType: "slipPrevention", plan: { rounds: next } }) }).catch(() => {});
    }
  }

  function startRound() {
    setActive(true); setThemeIdx(0); setStage("root");
    setRoundAnswers({}); setLastResult(null);
  }

  function goToNextThemeOrFinish(nextAnswers) {
    if (themeIdx < THEMES_PER_ROUND - 1) {
      setThemeIdx(themeIdx + 1); setStage("root");
    } else {
      finishRound(nextAnswers);
    }
  }

  function answerRootChoice(opt) {
    const isConcerning = (theme.root.concerning || []).includes(opt);
    const qaEntry = { label: theme.label, q: theme.root.q, a: opt, concerning: isConcerning, suggest: theme.suggest, patternInsight: theme.patternInsight, microExercise: theme.microExercise };
    const nextAnswers = { ...roundAnswers, [theme.key]: qaEntry };
    setRoundAnswers(nextAnswers);

    // تطبیقی: اگر همین موضوع در ۲ دوره‌یِ اخیر هم نگران‌کننده بوده، این‌بار سوالِ عمیق‌ترِ سی‌بی‌تی/اکت بپرس
    const recentRounds = rounds.slice(-2);
    const recurredRecently = isConcerning && recentRounds.filter((r) => r.answers[theme.label]?.concerning).length >= 1;
    const pool = (recurredRecently && theme.cbtActFollowUps?.length) ? theme.cbtActFollowUps : (theme.followUps || []);
    if (pool.length === 0) { goToNextThemeOrFinish(nextAnswers); return; }
    const pick = pool[Math.floor(Math.random() * pool.length)];
    setDynamicItem({ ...pick, isDeepDive: recurredRecently && theme.cbtActFollowUps?.length > 0 });
    setStage("dynamic");
  }

  function answerDynamicChoice(opt) {
    const prevEntry = roundAnswers[theme.key];
    const merged = { ...prevEntry, followUpQ: dynamicItem.q, followUpA: opt };
    const nextAnswers = { ...roundAnswers, [theme.key]: merged };
    setRoundAnswers(nextAnswers);
    setDynamicItem(null);
    goToNextThemeOrFinish(nextAnswers);
  }

  function finishRound(finalAnswers) {
    const concerningThemes = Object.values(finalAnswers).filter((a) => a.concerning);
    const prevRound = rounds[rounds.length - 1];
    let comparison = [];
    if (prevRound) {
      Object.values(finalAnswers).forEach((a) => {
        const prevA = prevRound.answers[a.label];
        if (prevA && prevA.concerning && a.concerning) comparison.push(`«${a.label}» دو دوره‌یِ پیاپی نگران‌کننده بوده — توجهِ بیشتری نیاز دارد.`);
      });
    }
    const nextDate = Date.now() + 2 * 86400000;
    const roundRecord = { ts: Date.now(), nextDate, answers: Object.fromEntries(Object.values(finalAnswers).map((a) => [a.label, a])) };
    const nextRounds = [...rounds, roundRecord];
    persistRounds(nextRounds);
    setLastResult({ concerningThemes, comparison, nextDate });
    setActive(false);
  }

  const nextDue = rounds.length ? rounds[rounds.length - 1].nextDate : null;
  const isDue = !nextDue || Date.now() >= nextDue;

  return (
    <Card>
      <button onClick={onBack} style={{ border: "none", background: "none", color: "#17383D", fontSize: 12, cursor: "pointer", marginBottom: 10 }}>‹ بازگشت</button>
      <h2 style={{ fontSize: 17, fontWeight: 800, color: "#1F2D3D", marginBottom: 4 }}>🛑 خودآگاهیِ دوره‌ای — پیشگیری از خیانت</h2>
      <p style={{ fontSize: 11.5, color: "#8CA3B0", marginBottom: 16 }}>هر دوره ۶ موضوعِ چرخشی (۱۲ سوالِ گزینه‌ای) می‌پرسد. کاملاً خصوصی، بدونِ نامِ افراد.</p>

      {!active && !lastResult && (
        <>
          {nextDue && (
            <p style={{ fontSize: 12, color: isDue ? "#B9822F" : "#4C8778", marginBottom: 10 }}>
              {isDue ? "⏰ زمانِ دوره‌ی بعدی رسیده." : `دوره‌ی بعدی: ${new Date(nextDue).toLocaleDateString("fa-IR")}`}
            </p>
          )}
          <button onClick={startRound} style={{ width: "100%", padding: "12px", borderRadius: 10, border: "none", background: "#B9822F", color: "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer" }}>
            {rounds.length === 0 ? "شروعِ اولین دوره" : "شروعِ دوره‌ی جدید"}
          </button>
          <button onClick={() => setShowTechniqueLibrary(true)} style={{ width: "100%", padding: "11px", borderRadius: 10, border: "1.5px solid #B9822F", background: "#fff", color: "#B9822F", fontWeight: 700, fontSize: 12.5, cursor: "pointer", marginTop: 8 }}>
            🧰 کتابخانه‌ی تکنیک‌ها (۴۰ تکنیکِ تخصصی)
          </button>
        </>
      )}

      {showTechniqueLibrary && (
        <div style={{ marginTop: 14 }}>
          <p style={{ fontSize: 12.5, fontWeight: 700, color: "#1F2D3D", marginBottom: 10 }}>🧰 کتابخانه‌ی تکنیک‌هایِ پیشگیری</p>
          {SLIP_THEMES.map((theme) => (
            <div key={theme.key} style={{ marginBottom: 8 }}>
              <button onClick={() => setExpandedTechniques((prev) => ({ ...prev, [theme.key]: !prev[theme.key] }))}
                style={{ width: "100%", textAlign: "right", padding: "10px 12px", borderRadius: 8, border: "1px solid #E8C9BC", background: "#FBF3E2", color: "#7A5B2E", fontSize: 12, fontWeight: 700, cursor: "pointer" }}>
                {expandedTechniques[theme.key] ? "▲ " : "▼ "}{theme.label} ({theme.techniques?.length || 0} تکنیک)
              </button>
              {expandedTechniques[theme.key] && theme.techniques && (
                <div style={{ marginTop: 6 }}>
                  {theme.techniques.map((t, ti) => (
                    <div key={ti} style={{ background: "#fff", border: "1px solid #F0E6D8", borderRadius: 8, padding: "10px 12px", marginBottom: 6 }}>
                      <p style={{ fontSize: 11.5, fontWeight: 700, color: "#7A5B2E", margin: "0 0 4px" }}>{ti + 1}. {t.name}</p>
                      <p style={{ fontSize: 11, color: "#3A4A52", lineHeight: 1.8, margin: "0 0 4px" }}>{t.howTo}</p>
                      <p style={{ fontSize: 10, color: "#8CA3B0", margin: 0 }}>💡 {t.effect}</p>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}
          <button onClick={() => setShowTechniqueLibrary(false)} style={{ width: "100%", padding: "9px", borderRadius: 10, border: "none", background: "transparent", color: "#8CA3B0", cursor: "pointer", fontSize: 12 }}>بستنِ کتابخانه</button>
        </div>
      )}

      {active && stage === "root" && (
        <div style={{ background: "#FBF3E2", borderRadius: 14, padding: "16px", marginBottom: 16 }}>
          <p style={{ fontSize: 10, color: "#B9822F", fontWeight: 700, marginBottom: 6 }}>موضوع {themeIdx + 1} از {THEMES_PER_ROUND} — {theme.label}</p>
          <p style={{ fontSize: 14, fontWeight: 700, color: "#7A5B2E", marginBottom: 12, lineHeight: 1.9 }}>{theme.root.q}</p>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {theme.root.options.map((opt) => (
              <button key={opt} onClick={() => answerRootChoice(opt)}
                style={{ padding: "11px", borderRadius: 10, border: "1px solid #E8C888", background: "#fff", color: "#7A5B2E", fontWeight: 700, fontSize: 13, cursor: "pointer", textAlign: "right" }}>
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}

      {active && stage === "dynamic" && dynamicItem && (
        <div style={{ background: "#FBF3E2", borderRadius: 14, padding: "16px", marginBottom: 16 }}>
          <p style={{ fontSize: 10, color: "#B9822F", fontWeight: 700, marginBottom: 6 }}>
            موضوع {themeIdx + 1} از {THEMES_PER_ROUND} — {theme.label} · {dynamicItem.isDeepDive ? "🧠 سوالِ عمیق‌تر (بر پایه‌ی تکرارِ این الگو)" : "سوالِ پیگیری"}
          </p>
          <p style={{ fontSize: 14, fontWeight: 700, color: "#7A5B2E", marginBottom: 12, lineHeight: 1.9 }}>{dynamicItem.q}</p>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {dynamicItem.options.map((opt) => (
              <button key={opt} onClick={() => answerDynamicChoice(opt)}
                style={{ padding: "11px", borderRadius: 10, border: "1px solid #E8C888", background: "#fff", color: "#7A5B2E", fontWeight: 700, fontSize: 13, cursor: "pointer", textAlign: "right" }}>
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}

      {lastResult && (
        <div style={{ background: "#F3F8F5", borderRadius: 14, padding: "16px", marginBottom: 16 }}>
          <p style={{ fontSize: 13, fontWeight: 700, color: "#4C8778", marginBottom: 10 }}>✅ این دوره تمام شد.</p>
          {lastResult.concerningThemes.length === 0 ? (
            <div>
              <p style={{ fontSize: 12.5, color: "#4C8778", marginBottom: 10 }}>در این دوره، هیچ موردِ نگران‌کننده‌ای ثبت نشد. 🌱</p>
              <a onClick={() => window.__naghsheOpenModerate && window.__naghsheOpenModerate()}
                style={{ fontSize: 10.5, color: "#8CA3B0", cursor: "pointer", textDecoration: "underline" }}>
                برایِ تقویتِ بیشترِ رابطه، حتی در حالتِ خوب، می‌توانید نگاهی به «افزایشِ وفاداری» هم بیندازید ←
              </a>
            </div>
          ) : (
            <>
              {lastResult.concerningThemes.length >= 2 && (
                <div style={{ background: "#FBF3E2", borderRadius: 10, padding: "12px 14px", marginBottom: 14, border: "1px solid #E8D8B0" }}>
                  <p style={{ fontSize: 12, fontWeight: 700, color: "#7A5B2E", margin: "0 0 6px" }}>🧩 تصویرِ کلی‌تر</p>
                  <p style={{ fontSize: 12, color: "#5A4020", lineHeight: 1.9, margin: "0 0 10px" }}>
                    در این دوره، {lastResult.concerningThemes.length} موضوعِ متفاوت («{lastResult.concerningThemes.map((c) => c.label).join("»، «")}») هم‌زمان دیده شدند. وقتی چند الگو با هم ظاهر می‌شوند، معمولاً یک ریشه‌ی مشترک دارند — مثلاً فاصله‌ی عاطفیِ کلی، یا دوره‌ای از استرسِ زندگی.
                  </p>
                  <AppointmentRequestButton context="چند الگویِ هم‌زمان در پیشگیریِ خیانت" userToken={userToken} />
                </div>
              )}
              <p style={{ fontSize: 12.5, fontWeight: 700, color: "#A6432F", marginBottom: 8 }}>الگوهایی که در پاسخ‌هایتان دیده شد:</p>
              {lastResult.concerningThemes.map((c, i) => (
                <div key={i} style={{ background: "#fff", borderRadius: 10, padding: "10px 12px", marginBottom: 8 }}>
                  {c.patternInsight ? (
                    <>
                      <p style={{ fontSize: 12.5, fontWeight: 700, color: "#1F2D3D", margin: "0 0 4px" }}>🔎 {c.patternInsight.title}</p>
                      <p style={{ fontSize: 11.5, color: "#5A7080", lineHeight: 1.8, margin: "0 0 10px" }}>{c.patternInsight.explanation}</p>
                    </>
                  ) : (
                    <p style={{ fontSize: 12, fontWeight: 700, color: "#1F2D3D", margin: "0 0 5px" }}>{c.label}</p>
                  )}
                  {c.microExercise && (
                    <div style={{ background: "#F3F8F5", borderRadius: 8, padding: "10px", marginBottom: 10 }}>
                      <p style={{ fontSize: 11, fontWeight: 700, color: "#4C8778", margin: "0 0 4px" }}>🌱 یک تمرینِ رایگان، همین حالا:</p>
                      <p style={{ fontSize: 11.5, color: "#3A4A52", lineHeight: 1.8, margin: 0 }}>{c.microExercise}</p>
                    </div>
                  )}
                  {c.techniques && c.techniques.length > 0 && (
                    <div style={{ marginBottom: 10 }}>
                      <button onClick={() => setExpandedTechniques((prev) => ({ ...prev, [c.key]: !prev[c.key] }))}
                        style={{ width: "100%", textAlign: "right", padding: "8px 10px", borderRadius: 8, border: "1px solid #E8C9BC", background: "#fff", color: "#8A5A4E", fontSize: 11, fontWeight: 700, cursor: "pointer" }}>
                        {expandedTechniques[c.key] ? "▲ بستنِ تکنیک‌ها" : `🧰 ${c.techniques.length} تکنیکِ تخصصی برایِ همین موضوع ▼`}
                      </button>
                      {expandedTechniques[c.key] && (
                        <div style={{ marginTop: 8 }}>
                          {c.techniques.map((t, ti) => (
                            <div key={ti} style={{ background: "#fff", border: "1px solid #F0E6D8", borderRadius: 8, padding: "10px 12px", marginBottom: 6 }}>
                              <p style={{ fontSize: 11.5, fontWeight: 700, color: "#7A5B2E", margin: "0 0 4px" }}>{ti + 1}. {t.name}</p>
                              <p style={{ fontSize: 11, color: "#3A4A52", lineHeight: 1.8, margin: "0 0 4px" }}>{t.howTo}</p>
                              <p style={{ fontSize: 10, color: "#8CA3B0", margin: 0 }}>💡 {t.effect}</p>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  )}
                  <a onClick={() => window.__naghsheOpenModerate && window.__naghsheOpenModerate()}
                    style={{ fontSize: 10.5, color: "#8A5A4E", cursor: "pointer", textDecoration: "underline" }}>
                    برایِ کارِ عمیق‌تر: {c.suggest} ←
                  </a>
                </div>
              ))}
              {lastResult.comparison.length > 0 && (
                <div style={{ marginTop: 8 }}>
                  {lastResult.comparison.map((c, i) => <p key={i} style={{ fontSize: 11, color: "#A6432F", margin: "4px 0" }}>⚠ {c}</p>)}
                </div>
              )}
            </>
          )}
          <p style={{ fontSize: 11, color: "#8CA3B0", marginTop: 10 }}>دوره‌ی بعدی: {new Date(lastResult.nextDate).toLocaleDateString("fa-IR")}</p>
        </div>
      )}

      {rounds.length > 0 && (
        <>
          {(() => {
            const chartRounds = rounds.slice(-10);
            const maxConcerning = Math.max(1, ...chartRounds.map((r) => Object.values(r.answers).filter((a) => a.concerning).length));
            const barW = 24, gap = 8, chartH = 90;
            const svgW = chartRounds.length * (barW + gap);
            return (
              <div style={{ background: "#fff", border: "1px solid #EDF2F5", borderRadius: 14, padding: "16px", marginBottom: 16 }}>
                <p style={{ fontSize: 13, fontWeight: 700, color: "#1F2D3D", marginBottom: 4 }}>📈 نمودارِ روندِ شما</p>
                <p style={{ fontSize: 10.5, color: "#8CA3B0", marginBottom: 12 }}>تعدادِ الگوهایِ نگران‌کننده، دوره‌به‌دوره (هرچه پایین‌تر، بهتر)</p>
                <svg width="100%" height={chartH + 24} viewBox={`0 0 ${svgW} ${chartH + 24}`} style={{ overflow: "visible" }}>
                  {chartRounds.map((r, i) => {
                    const count = Object.values(r.answers).filter((a) => a.concerning).length;
                    const h = Math.max(4, (count / maxConcerning) * chartH);
                    const x = i * (barW + gap);
                    const color = count === 0 ? "#4C8778" : count <= 2 ? "#B8873A" : "#A6432F";
                    return (
                      <g key={i}>
                        <rect x={x} y={chartH - h} width={barW} height={h} rx={4} fill={color} opacity={i === chartRounds.length - 1 ? 1 : 0.55} />
                        <text x={x + barW / 2} y={chartH + 14} fontSize="8" fill="#8CA3B0" textAnchor="middle">
                          {new Date(r.ts).toLocaleDateString("fa-IR", { month: "numeric", day: "numeric" })}
                        </text>
                      </g>
                    );
                  })}
                </svg>
                {chartRounds.length >= 3 && (() => {
                  const firstHalf = chartRounds.slice(0, Math.ceil(chartRounds.length / 2));
                  const secondHalf = chartRounds.slice(Math.ceil(chartRounds.length / 2));
                  const avg = (arr) => arr.reduce((s, r) => s + Object.values(r.answers).filter((a) => a.concerning).length, 0) / arr.length;
                  const trend = avg(secondHalf) - avg(firstHalf);
                  return (
                    <p style={{ fontSize: 11.5, fontWeight: 700, color: trend < -0.3 ? "#4C8778" : trend > 0.3 ? "#A6432F" : "#8CA3B0", marginTop: 10 }}>
                      {trend < -0.3 ? "🌱 روندِ شما رو‌به‌بهبود است — ادامه دهید." : trend > 0.3 ? "⚠ روندِ اخیر نسبت به قبل، نگران‌کننده‌تر شده — شاید وقتِ توجهِ بیشتری باشد." : "روندتان نسبتاً ثابت است."}
                    </p>
                  );
                })()}
              </div>
            );
          })()}
        </>
      )}

      <div style={{ background: "#F7FAFC", borderRadius: 14, padding: "16px", marginBottom: 16 }}>
        <p style={{ fontSize: 12.5, fontWeight: 700, color: "#1F2D3D", marginBottom: 8 }}>💡 ۱۰ راهکارِ کلی برایِ پیشگیری</p>
        {SLIP_STRATEGIES.map((s, i) => (
          <p key={i} style={{ fontSize: 11.5, color: "#3A4A52", margin: "0 0 6px", lineHeight: 1.8 }}>{i + 1}. {s}</p>
        ))}
      </div>

      {rounds.length > 0 && (
        <>
          {rounds.length >= 2 && (() => {
            const last14 = rounds.slice(-14);
            const maxConcern = Math.max(1, ...last14.map((r) => Object.values(r.answers).filter((a) => a.concerning).length));
            const chartW = 300, chartH = 90, barGap = 4;
            const barW = (chartW - barGap * (last14.length - 1)) / last14.length;
            return (
              <div style={{ background: "#fff", border: "1px solid #EDF2F5", borderRadius: 14, padding: "16px", marginBottom: 16 }}>
                <p style={{ fontSize: 12.5, fontWeight: 700, color: "#1F2D3D", marginBottom: 10 }}>📈 روندِ نگرانی در {last14.length} دوره‌ی اخیر</p>
                <svg viewBox={`0 0 ${chartW} ${chartH + 20}`} width="100%" height={chartH + 20}>
                  {last14.map((r, i) => {
                    const cCount = Object.values(r.answers).filter((a) => a.concerning).length;
                    const h = (cCount / maxConcern) * chartH;
                    const x = i * (barW + barGap);
                    const color = cCount === 0 ? "#4C8778" : cCount <= 1 ? "#B8873A" : "#A6432F";
                    return (
                      <g key={i}>
                        <rect x={x} y={chartH - h} width={barW} height={Math.max(h, 3)} rx={2} fill={color} opacity={0.85} />
                        {cCount > 0 && <text x={x + barW / 2} y={chartH - h - 4} fontSize="8" fill={color} textAnchor="middle">{cCount}</text>}
                      </g>
                    );
                  })}
                  <line x1="0" y1={chartH} x2={chartW} y2={chartH} stroke="#EDF2F5" strokeWidth="1" />
                </svg>
                <p style={{ fontSize: 10, color: "#8CA3B0", marginTop: 6, textAlign: "center" }}>هر ستون یک دوره است؛ ارتفاعِ بیشتر = موضوعاتِ نگران‌کننده‌ی بیشتر در آن دوره</p>
              </div>
            );
          })()}
          {(() => {
            const oneWeekAgo = Date.now() - 7 * 86400000;
            const weekRounds = rounds.filter((r) => r.ts >= oneWeekAgo);
            if (weekRounds.length === 0) return null;
            const freq = {};
            weekRounds.forEach((r) => {
              Object.values(r.answers).forEach((a) => {
                if (a.concerning) freq[a.label] = (freq[a.label] || 0) + 1;
              });
            });
            const sorted = Object.entries(freq).sort((a, b) => b[1] - a[1]);
            return (
              <div style={{ background: "#FBF3E2", borderRadius: 14, padding: "16px", marginBottom: 16 }}>
                <p style={{ fontSize: 13, fontWeight: 700, color: "#7A5B2E", marginBottom: 8 }}>📊 خلاصه‌ی این هفته ({weekRounds.length} دوره)</p>
                {sorted.length === 0 ? (
                  <p style={{ fontSize: 12, color: "#4C8778" }}>هیچ الگویِ تکرارشونده‌ای این هفته دیده نشد. 🌱</p>
                ) : (
                  <>
                    <p style={{ fontSize: 11.5, color: "#7A5B2E", marginBottom: 8 }}>موضوعاتی که بیش از یک‌بار تکرار شدند:</p>
                    {sorted.map(([label, freqCount], i) => (
                      <p key={i} style={{ fontSize: 12, color: "#5A4020", margin: "0 0 4px" }}>
                        • <b>{label}</b> — {freqCount} از {weekRounds.length} دوره
                      </p>
                    ))}
                  </>
                )}
              </div>
            );
          })()}
          <p style={{ fontSize: 12.5, fontWeight: 700, color: "#1F2D3D", margin: "18px 0 8px" }}>📅 تاریخچه‌ی دوره‌ها ({rounds.length})</p>
          {rounds.slice().reverse().map((r, i) => {
            const concerningCount = Object.values(r.answers).filter((a) => a.concerning).length;
            return (
              <div key={i} style={{ background: "#F7FAFC", borderRadius: 10, padding: "8px 12px", marginBottom: 6, display: "flex", justifyContent: "space-between" }}>
                <span style={{ fontSize: 11.5, color: "#3A4A52" }}>{new Date(r.ts).toLocaleDateString("fa-IR")}</span>
                <span style={{ fontSize: 11, color: concerningCount ? "#A6432F" : "#4C8778", fontWeight: 700 }}>{concerningCount ? `${concerningCount} موردِ توجه` : "بدونِ مورد"}</span>
              </div>
            );
          })}
        </>
      )}
    </Card>
  );
}

function SafetyPlanScreen({ onBack, userEmail, userToken }) {
  const storageKey = `safety_plan_${userEmail || "anon"}`;
  const [plan, setPlan] = useState(() => {
    try { return JSON.parse(localStorage.getItem(storageKey)) || { warningSigns: "", copingStrategies: "", contacts: "", safePlaces: "" }; }
    catch (e) { return { warningSigns: "", copingStrategies: "", contacts: "", safePlaces: "" }; }
  });
  const [saved, setSaved] = useState(true);
  const [saveError, setSaveError] = useState(false);

  function updateField(field, value) {
    const next = { ...plan, [field]: value };
    setPlan(next);
    setSaved(false);
    setSaveError(false);
    try { localStorage.setItem(storageKey, JSON.stringify(next)); } catch (e) {}
  }

  useEffect(() => {
    if (saved || !userToken) return;
    const t = setTimeout(() => {
      fetchWithTimeout("/api/safety-plan", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token: userToken, plan }),
      }).then((r) => { if (r.ok) { setSaved(true); setSaveError(false); } else { setSaveError(true); } })
        .catch(() => setSaveError(true));
    }, 1200);
    return () => clearTimeout(t);
  }, [plan, saved, userToken]);

  const fields = [
    { key: "warningSigns", label: "🚩 نشانه‌هایِ هشدارِ من", placeholder: "چه‌احساس/فکر/رفتاری به من می‌گوید دارم وارد بحران می‌شوم؟ (مثلاً: بی‌خوابیِ شدید، افکارِ تکرارشونده‌ی منفی...)" },
    { key: "copingStrategies", label: "🧘 کارهایی که به من کمک می‌کند آرام شوم", placeholder: "مثلاً: تنفسِ ۴-۷-۸، تماس با فلان دوست، پیاده‌روی..." },
    { key: "safePlaces", label: "🏠 مکان‌ها/افرادی که در آن‌ها احساسِ امنیت می‌کنم", placeholder: "مثلاً: خانه‌ی مادرم، پارکِ نزدیکِ خانه..." },
    { key: "contacts", label: "📞 افرادی که در بحران با آن‌ها تماس می‌گیرم", placeholder: "نام و شماره‌ی حداقل ۲-۳ نفرِ قابلِ‌اعتماد..." },
  ];

  return (
    <Card>
      <button onClick={onBack} style={{ border: "none", background: "none", color: "#17383D", fontSize: 12, cursor: "pointer", marginBottom: 10 }}>‹ بازگشت</button>
      <h2 style={{ fontSize: 17, fontWeight: 800, color: "#1F2D3D", marginBottom: 4 }}>🛡️ برنامه‌ی ایمنیِ من</h2>
      <p style={{ fontSize: 11.5, color: "#8CA3B0", marginBottom: 16 }}>
        این صفحه، مستقل از جلسات، همیشه در دسترسِ شماست — برایِ لحظاتی که احساسِ بحران می‌کنید. همین حالا، در آرامش، پرش کنید.
      </p>
      {fields.map((f) => (
        <div key={f.key} style={{ marginBottom: 14 }}>
          <p style={{ fontSize: 12, fontWeight: 700, color: "#1F2D3D", margin: "0 0 6px" }}>{f.label}</p>
          <textarea value={plan[f.key]} onChange={(e) => updateField(f.key, e.target.value)} placeholder={f.placeholder}
            style={{ width: "100%", minHeight: 70, padding: "9px 11px", borderRadius: 10, border: "1px solid #DCE8F0", fontSize: 12.5, fontFamily: "inherit", resize: "vertical", boxSizing: "border-box" }} />
        </div>
      ))}
      {userEmail && <p style={{ fontSize: 9.5, color: saveError ? "#A6432F" : saved ? "#8CA3B0" : "#B9822F", textAlign: "center" }}>{saveError ? "⚠️ ذخیره در سرور ناموفق بود — فقط روی گوشی مانده" : saved ? "ذخیره شد ✓" : "در حالِ ذخیره..."}</p>}
      <div style={{ background: "#FBF0EC", border: "1px solid #E8C9BC", borderRadius: 10, padding: "12px 14px", marginTop: 8 }}>
        <p style={{ fontSize: 12, color: "#8A5A4E", fontWeight: 700, margin: "0 0 4px" }}>📞 اورژانسِ فوری</p>
        <p style={{ fontSize: 12, color: "#8A5A4E", margin: 0 }}>در بحرانِ حاد، همین حالا با اورژانس (۱۱۵) یا نزدیک‌ترین مرکزِ درمانی تماس بگیرید — منتظرِ نوبتِ جلسه نمانید.</p>
        <a href={CONSULT_BOOKING_LINK} style={{ display: "inline-block", marginTop: 6, fontSize: 12, fontWeight: 700, color: "#17383D" }}>📞 تماس با دفتر: {BRAND.phone}</a>
      </div>
    </Card>
  );
}

// ---------- چک‌اینِ دوره‌ای — پایشِ کوتاهِ خلق/رابطه + پیشنهادِ خودکارِ جلسه ----------
function CheckinScreen({ onBack, userEmail, userToken, unlockedSessions, defaultIntervalDays }) {
  const [answers, setAnswers] = useState({});
  const [intervalDays, setIntervalDays] = useState(defaultIntervalDays || 7);
  const [submitted, setSubmitted] = useState(false);
  const [saving, setSaving] = useState(false);

  function setAnswer(key, val) {
    setAnswers((prev) => ({ ...prev, [key]: val }));
  }

  const allAnswered = CHECKIN_ITEMS.every((it) => answers[it.key] != null);
  const lowItems = CHECKIN_ITEMS.filter((it) => answers[it.key] != null && answers[it.key] <= 2);

  const [suggestions, setSuggestions] = useState([]);

  // پیشنهادِ جلسه بر اساسِ آیتم‌هایِ کم‌امتیاز: جست‌وجویِ سمتِ سرور در جلساتِ بازشده‌یِ کاربر
  useEffect(() => {
    if (!submitted || !unlockedSessions?.length || lowItems.length === 0) { setSuggestions([]); return; }
    fetchWithTimeout("/api/session-suggest", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        unlockedSessions,
        keywords: lowItems.map((item) => ({ keyword: item.keyword, reason: item.q })),
      }),
    })
      .then((r) => r.json())
      .then((d) => { if (d.ok) setSuggestions(d.suggestions); })
      .catch(() => {});
  }, [submitted]);

  async function handleSubmit() {
    setSaving(true);
    try {
      await fetchWithTimeout("/api/checkin", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token: userToken, answers, intervalDays }),
      });
    } catch (e) {}
    setSaving(false);
    setSubmitted(true);
  }

  if (submitted) {
    return (
      <Card>
        <button onClick={onBack} style={{ border: "none", background: "none", color: "#17383D", fontSize: 12, cursor: "pointer", marginBottom: 10 }}>‹ بازگشت</button>
        <h2 style={{ fontSize: 17, fontWeight: 800, color: "#1F2D3D", marginBottom: 4 }}>✅ چک‌این ثبت شد</h2>
        <p style={{ fontSize: 11.5, color: "#8CA3B0", marginBottom: 16 }}>ممنون — چک‌اینِ بعدی طبقِ زمان‌بندی‌تان یادآوری می‌شود.</p>
        {suggestions.length > 0 ? (
          <>
            <p style={{ fontSize: 12.5, fontWeight: 700, color: "#B9822F", margin: "0 0 10px" }}>بر اساسِ پاسخ‌هایتان، پیشنهاد می‌کنیم این جلسات را مرور کنید:</p>
            {suggestions.map((s, i) => (
              <div key={i} style={{ background: "#FBF3E2", borderRadius: 10, padding: "10px 12px", marginBottom: 8 }}>
                <p style={{ fontSize: 12, fontWeight: 700, color: "#1F2D3D", margin: "0 0 3px" }}>{s.title}</p>
                <p style={{ fontSize: 10.5, color: "#7A5B2E", margin: 0 }}>دلیل: {s.reason}</p>
              </div>
            ))}
          </>
        ) : (
          <div style={{ background: "#F3F8F5", borderRadius: 10, padding: "12px 14px" }}>
            <p style={{ fontSize: 12, color: "#4C8778", margin: 0 }}>🌱 وضعیتتان خوب به‌نظر می‌رسد — همین مسیر را ادامه دهید.</p>
          </div>
        )}
      </Card>
    );
  }

  return (
    <Card>
      <button onClick={onBack} style={{ border: "none", background: "none", color: "#17383D", fontSize: 12, cursor: "pointer", marginBottom: 10 }}>‹ بازگشت</button>
      <h2 style={{ fontSize: 17, fontWeight: 800, color: "#1F2D3D", marginBottom: 4 }}>📋 چک‌اینِ دوره‌ای</h2>
      <p style={{ fontSize: 11.5, color: "#8CA3B0", marginBottom: 16 }}>۶ سوالِ کوتاه، ۲ دقیقه — برایِ رصدِ روندِ حالتان بینِ جلسات.</p>

      {CHECKIN_ITEMS.map((item) => (
        <div key={item.key} style={{ marginBottom: 14 }}>
          <p style={{ fontSize: 12, fontWeight: 600, color: "#1F2D3D", margin: "0 0 6px" }}>{item.q}</p>
          <div style={{ display: "flex", gap: 5 }}>
            {[1, 2, 3, 4, 5].map((n) => (
              <button key={n} onClick={() => setAnswer(item.key, n)}
                style={{ flex: 1, padding: "8px 0", borderRadius: 8, border: `1.5px solid ${answers[item.key] === n ? "#17383D" : "#DCE8F0"}`, background: answers[item.key] === n ? "#17383D" : "#fff", color: answers[item.key] === n ? "#fff" : "#5A7080", fontWeight: 700, fontSize: 12, cursor: "pointer" }}>
                {n}
              </button>
            ))}
          </div>
        </div>
      ))}

      <div style={{ background: "#F7FAFC", borderRadius: 10, padding: "10px 12px", marginBottom: 16 }}>
        <p style={{ fontSize: 11.5, fontWeight: 700, color: "#3A4A52", margin: "0 0 6px" }}>هر چند روز یک‌بار یادآوریِ چک‌این می‌خواهید؟</p>
        <div style={{ display: "flex", gap: 6 }}>
          {[4, 7, 14].map((d) => (
            <button key={d} onClick={() => setIntervalDays(d)}
              style={{ flex: 1, padding: "8px 0", borderRadius: 8, border: `1.5px solid ${intervalDays === d ? "#4C8778" : "#DCE8F0"}`, background: intervalDays === d ? "#4C8778" : "#fff", color: intervalDays === d ? "#fff" : "#5A7080", fontWeight: 700, fontSize: 11.5, cursor: "pointer" }}>
              هر {d} روز
            </button>
          ))}
        </div>
        {defaultIntervalDays && <p style={{ fontSize: 10, color: "#8CA3B0", margin: "6px 0 0" }}>پیشنهادِ ما بر اساسِ مسیرِ درمانی‌تان: هر {defaultIntervalDays} روز.</p>}
      </div>

      <button onClick={handleSubmit} disabled={!allAnswered || saving}
        style={{ width: "100%", padding: "12px", borderRadius: 12, border: "none", background: allAnswered ? "#17383D" : "#C9DEE8", color: "#fff", fontWeight: 700, fontSize: 13, cursor: allAnswered ? "pointer" : "default" }}>
        {saving ? "در حالِ ثبت..." : "ثبتِ چک‌این"}
      </button>
    </Card>
  );
}


function PartnerSyncWidget({ userEmail, userToken, pkgKey, totalSessions }) {
  const storageKey = `partner_email_${userEmail}`;
  const [partnerEmail, setPartnerEmailState] = useState(() => {
    try { return localStorage.getItem(storageKey) || ""; } catch (e) { return ""; }
  });
  const [inputVal, setInputVal] = useState("");
  const [partnerCount, setPartnerCount] = useState(null);
  const [msg, setMsg] = useState("");

  useEffect(() => {
    if (partnerEmail) fetchPartnerProgress();
  }, [partnerEmail, pkgKey]);

  function fetchPartnerProgress() {
    if (!userToken) return;
    fetchWithTimeout(`/api/partner-link?token=${encodeURIComponent(userToken)}&pkgKey=${encodeURIComponent(pkgKey)}`)
      .then((r) => r.json())
      .then((d) => { if (d.ok) setPartnerCount(d.unlockedCount); })
      .catch(() => {});
  }

  function linkPartner() {
    if (!inputVal || !userToken) return;
    fetchWithTimeout("/api/partner-link", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ token: userToken, partnerEmail: inputVal }),
    }).then(() => {
      setPartnerEmailState(inputVal);
      try { localStorage.setItem(storageKey, inputVal); } catch (e) {}
      setMsg("اتصال برقرار شد ✓");
      fetchPartnerProgress();
    }).catch(() => setMsg("خطا در اتصال"));
  }

  if (!userEmail) return null;

  return (
    <div style={{ background: "#F1E8D4", borderRadius: 12, padding: "12px 14px", marginBottom: 14 }}>
      <p style={{ fontSize: 12, fontWeight: 700, color: "#17383D", margin: "0 0 8px" }}>👫 هماهنگیِ زوجین</p>
      {!partnerEmail ? (
        <>
          <p style={{ fontSize: 11, color: "#3A4A52", margin: "0 0 8px" }}>ایمیلِ حسابِ همسرتان را وارد کنید تا پیشرفتِ او را هم اینجا ببینید.</p>
          <div style={{ display: "flex", gap: 6 }}>
            <input value={inputVal} onChange={(e) => setInputVal(e.target.value)} placeholder="ایمیلِ همسر"
              style={{ flex: 1, padding: "7px 9px", borderRadius: 8, border: "1px solid #C9DEE8", fontSize: 12 }} />
            <button onClick={linkPartner}
              style={{ padding: "7px 14px", borderRadius: 8, border: "none", background: "linear-gradient(160deg, #2C5560, #17383D 55%, #0E2529)", color: "#fff", fontWeight: 700, boxShadow: "0 8px 16px rgba(23,56,61,0.35), inset 0 1.5px 0 rgba(255,255,255,0.25), inset 0 -2px 4px rgba(0,0,0,0.2)", transition: "transform 0.15s ease", fontSize: 11.5, cursor: "pointer" }}>
              اتصال
            </button>
          </div>
          {msg && <p style={{ fontSize: 10.5, color: "#4C8778", marginTop: 6 }}>{msg}</p>}
        </>
      ) : (
        <p style={{ fontSize: 12, color: "#1F2D3D", margin: 0 }}>
          همسرتان ({partnerEmail}) تا‌کنون <b>{partnerCount ?? "..."}</b> از {totalSessions} جلسه را باز کرده است.
        </p>
      )}
    </div>
  );
}

// ---------- Clearer radar chart with safety bands ----------
function RadarChart({ p1, p2, domains }) {
  const size = 360;
  const cx = size / 2, cy = size / 2 + 6, maxR = 122;
  const n = domains.length;
  const bands = [
    { from: 0, to: 0.25, color: "#F3D9D3" },
    { from: 0.25, to: 0.5, color: "#F5E7CC" },
    { from: 0.5, to: 0.75, color: "#EDF0CC" },
    { from: 0.75, to: 1, color: "#DDEBDD" },
  ];

  const ringPts = (r) => domains.map((_, j) => polar(cx, cy, maxR * r, (360 / n) * j));
  const ringPath = (r) => ringPts(r).map((p) => `${p.x},${p.y}`).join(" ");

  const pathFor = (scores) => {
    const pts = domains.map((d, i) => {
      const r = (scores[d.key] / 100) * maxR;
      return polar(cx, cy, r, (360 / n) * i);
    });
    return pts.map((p, i) => `${i === 0 ? "M" : "L"}${p.x},${p.y}`).join(" ") + "Z";
  };
  const vertexPts = (scores) => domains.map((d, i) => ({ ...polar(cx, cy, (scores[d.key] / 100) * maxR, (360 / n) * i), val: scores[d.key] }));

  return (
    <div>
      <svg viewBox={`0 0 ${size} ${size + 10}`} width="100%" style={{ maxWidth: 400, display: "block", margin: "0 auto" }}>
        {bands.map((b, i) => (
          <polygon key={i} points={ringPath(b.to)} fill={b.color} stroke="none" />
        ))}
        {[0.25, 0.5, 0.75, 1].map((r, i) => (
          <polygon key={i} points={ringPath(r)} fill="none" stroke="#FFFFFF" strokeWidth={1.5} />
        ))}
        {domains.map((_, i) => {
          const p = polar(cx, cy, maxR, (360 / n) * i);
          return <line key={i} x1={cx} y1={cy} x2={p.x} y2={p.y} stroke="#FFFFFF" strokeWidth={1.5} />;
        })}

        <path d={pathFor(p1)} fill="#17383D" fillOpacity={0.22} stroke="#17383D" strokeWidth={3} />
        <path d={pathFor(p2)} fill="#E8975C" fillOpacity={0.22} stroke="#E8975C" strokeWidth={3} />

        {vertexPts(p1).map((p, i) => (
          <g key={"a" + i}>
            <circle cx={p.x} cy={p.y} r={10} fill="#17383D" stroke="#fff" strokeWidth={1.5} />
            <text x={p.x} y={p.y + 0.5} textAnchor="middle" dominantBaseline="middle" fontSize="9" fontWeight="700" fill="#fff">{p.val}</text>
          </g>
        ))}
        {vertexPts(p2).map((p, i) => (
          <g key={"b" + i}>
            <circle cx={p.x} cy={p.y} r={10} fill="#E8975C" stroke="#fff" strokeWidth={1.5} />
            <text x={p.x} y={p.y + 0.5} textAnchor="middle" dominantBaseline="middle" fontSize="9" fontWeight="700" fill="#fff">{p.val}</text>
          </g>
        ))}

        {domains.map((d, i) => {
          const p = polar(cx, cy, maxR + 42, (360 / n) * i);
          const avg = Math.round((p1[d.key] + p2[d.key]) / 2);
          return (
            <g key={d.key}>
              <text x={p.x} y={p.y - 7} textAnchor="middle" dominantBaseline="middle" fontSize="12.5" fontWeight="700" fill="#2F4250">
                {d.short}
              </text>
              <text x={p.x} y={p.y + 9} textAnchor="middle" dominantBaseline="middle" fontSize="10.5" fontWeight="600" fill={LEVEL_COLOR[level(avg)]}>
                {avg}
              </text>
            </g>
          );
        })}
      </svg>
      <div style={{ display: "flex", justifyContent: "center", gap: 14, flexWrap: "wrap", fontSize: 10.5, color: "#7C8D97", marginTop: 4 }}>
        <span><span style={{ display: "inline-block", width: 9, height: 9, background: "#F3D9D3", borderRadius: 2, marginInlineEnd: 3 }} />تعهدِ پایین</span>
        <span><span style={{ display: "inline-block", width: 9, height: 9, background: "#F5E7CC", borderRadius: 2, marginInlineEnd: 3 }} />تعهدِ متوسط رو‌به‌پایین</span>
        <span><span style={{ display: "inline-block", width: 9, height: 9, background: "#EDF0CC", borderRadius: 2, marginInlineEnd: 3 }} />تعهدِ متوسط رو‌به‌بالا</span>
        <span><span style={{ display: "inline-block", width: 9, height: 9, background: "#DDEBDD", borderRadius: 2, marginInlineEnd: 3 }} />متعهد و پایبند</span>
      </div>
      <p style={{ textAlign: "center", fontSize: 11, color: "#8CA3B0", marginTop: 6 }}>
        هرچه نقطه به لبه‌ی بیرونی نزدیک‌تر باشد، تعهد و پایبندی در آن حیطه بیشتر است؛ نزدیکی به مرکز یعنی تعهدِ پایین‌تر و خطرِ بیشتر.
      </p>
    </div>
  );
}

// ---------- Unambiguous bar-chart readout (numbers on a 0-100 ruler) ----------
function DomainBarChart({ p1, p2, domains }) {
  return (
    <div style={{ padding: "4px 2px" }}>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 9.5, color: "#B7C6CE", padding: "0 0 4px", marginRight: 40 }}>
        <span>۰</span><span>۲۵</span><span>۵۰</span><span>۷۵</span><span>۱۰۰</span>
      </div>
      {domains.map((d) => (
        <div key={d.key} style={{ marginBottom: 14 }}>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: "#1F2D3D", marginBottom: 5 }}>{d.title}</div>
          {[{ label: "نفر ۱", val: p1[d.key], color: "#17383D" }, { label: "نفر ۲", val: p2[d.key], color: "#E8975C" }].map((row) => (
            <div key={row.label} style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 3 }}>
              <span style={{ fontSize: 10.5, color: row.color, width: 34, flexShrink: 0 }}>{row.label}</span>
              <div style={{ flex: 1, height: 14, background: "#EEF3F6", borderRadius: 7, overflow: "hidden", position: "relative" }}>
                {[25, 50, 75].map((m) => (
                  <div key={m} style={{ position: "absolute", right: `${m}%`, top: 0, bottom: 0, width: 1, background: "#fff" }} />
                ))}
                <div style={{ height: "100%", width: `${row.val}%`, background: row.color, borderRadius: 7 }} />
              </div>
              <span style={{ fontSize: 11.5, fontWeight: 700, color: row.color, width: 24, flexShrink: 0, textAlign: "left" }}>{row.val}</span>
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

// ---------- Main App ----------
function PricingTiers({ tier, scores, onOpenLibrary }) {
  const [chosenTrack, setChosenTrack] = useState(null);
  const [gateStep, setGateStep] = useState(2);
  if (tier === "healthy") return null;
  const weakestDomain = scores
    ? Object.entries(scores).sort((a, b) => a[1] - b[1])[0]?.[0]
    : null;

  if (!chosenTrack) {
    if (gateStep === 2) {
      return (
        <div style={{ marginTop: 18, padding: "16px 16px 14px", borderRadius: 18, background: "#FBF0EC", border: "1px solid #E8C9BC" }}>
          <p style={{ fontSize: 12.5, fontWeight: 700, color: "#8A5A4E", margin: "0 0 4px" }}>🕊️ درمانِ خیانتِ زناشویی</p>
          <p style={{ fontSize: 11.5, color: "#5A7080", lineHeight: 1.9, margin: "0 0 12px" }}>
            خیانتِ زناشویی در زندگیِ شما اتفاق افتاده (یا افشا شده) و می‌خواهید این آسیب را واقعاً درمان کنید — فارغ از این‌که در پایان تصمیم به ماندن بگیرید یا رفتن. این تصمیم، بعداً و در زمانِ خودتان گرفته می‌شود؛ همین حالا فقط برایِ بهبودی قدم بردارید.
          </p>
          <p style={{ fontSize: 12, color: "#3A4A52", lineHeight: 1.9, margin: "0 0 12px" }}>
            می‌خواهید مسیرِ درمانی به‌صورتِ **جلساتِ مشترک با همسرتان** باشد، یا یک **مسیرِ فردیِ مستقل** برایِ خودتان؟
          </p>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            <button onClick={() => setChosenTrack("advanced")}
              style={{ padding: "11px", borderRadius: 12, border: "none", background: "#8A5A4E", color: "#fff", fontWeight: 700, fontSize: 12.5, cursor: "pointer" }}>
              جلساتِ مشترکِ زوجین
            </button>
            <button onClick={() => setGateStep(3)}
              style={{ padding: "11px", borderRadius: 12, border: "1px solid #8A5A4E", background: "#fff", color: "#8A5A4E", fontWeight: 700, fontSize: 12.5, cursor: "pointer" }}>
              مسیرِ فردیِ مستقل
            </button>
          </div>
        </div>
      );
    }
    if (gateStep === 3) {
      return (
        <div style={{ marginTop: 18, padding: "16px 16px 14px", borderRadius: 18, background: "#FBF0EC", border: "1px solid #E8C9BC" }}>
          <button onClick={() => setGateStep(2)} style={{ border: "none", background: "none", color: "#8CA3B0", fontSize: 10.5, cursor: "pointer", marginBottom: 8, padding: 0 }}>‹ بازگشت</button>
          <p style={{ fontSize: 12, color: "#3A4A52", lineHeight: 1.9, margin: "0 0 12px" }}>
            شما در این ماجرا کدام نقش را دارید؟
          </p>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            <button onClick={() => setChosenTrack("betrayed")}
              style={{ padding: "11px", borderRadius: 12, border: "none", background: "#8A5A4E", color: "#fff", fontWeight: 700, fontSize: 12.5, cursor: "pointer" }}>
              خیانت‌دیده هستم
            </button>
            <button onClick={() => setChosenTrack("unfaithful")}
              style={{ padding: "11px", borderRadius: 12, border: "1px solid #8A5A4E", background: "#fff", color: "#8A5A4E", fontWeight: 700, fontSize: 12.5, cursor: "pointer" }}>
              خودم مرتکب خیانت شده‌ام
            </button>
          </div>
        </div>
      );
    }
  }

  const pkg = TREATMENT_PACKAGES[chosenTrack];
  const savings = pkg.inPersonEquivalent - pkg.price;
  const isPostInfidelity = chosenTrack !== "moderate";
  return (
    <div style={{
      marginTop: 18, padding: "16px 16px 14px", borderRadius: 18,
      background: isPostInfidelity ? "#FBF0EC" : "#F3F8F5",
      border: `1px solid ${isPostInfidelity ? "#E8C9BC" : "#CFE6D8"}`,
    }}>
      <button onClick={() => { setChosenTrack(null); setGateStep(2); }} style={{ border: "none", background: "none", color: "#8CA3B0", fontSize: 10.5, cursor: "pointer", marginBottom: 6, padding: 0 }}>
        ‹ تغییرِ پاسخ
      </button>
      <p style={{ fontSize: 13, fontWeight: 800, color: "#1F2D3D", margin: "0 0 6px" }}>
        {isPostInfidelity ? "🕊️ دوره‌ی درمانِ خیانت — خریدِ پکیج" : "🌱 دوره‌ی بهبودِ تعهد و پیشگیریِ خیانت — خریدِ پکیج"}
      </p>
      <p style={{ fontSize: 12, color: "#3A4A52", lineHeight: 1.9, margin: "0 0 12px" }}>
        این جلسات با رویکردهایِ علمیِ ACT، EFT و گاتمن طراحی شده و به‌محضِ خرید، همین‌جا در اپ برایتان باز می‌شود.
      </p>
      <div style={{ background: "#fff", borderRadius: 14, padding: "12px 14px", marginBottom: 10 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 4 }}>
          <span style={{ fontSize: 13, fontWeight: 800, color: "#1F2D3D" }}>{pkg.label} ({pkg.sessions} جلسه)</span>
          <span style={{ fontSize: 15, fontWeight: 800, color: "#17383D" }}>{toman(pkg.price)}</span>
        </div>
        <p style={{ fontSize: 11, color: "#8CA3B0", margin: "0 0 6px" }}>{pkg.note}</p>
        <p style={{ fontSize: 11, color: "#5A7080", margin: 0 }}>
          معادلِ حضوری: <span style={{ textDecoration: "line-through" }}>{toman(pkg.inPersonEquivalent)}</span>{" "}
          <span style={{ color: "#4C8778", fontWeight: 700 }}>({toman(savings)} صرفه‌جویی)</span>
        </p>
      </div>
      <button onClick={() => onOpenLibrary && onOpenLibrary(chosenTrack, weakestDomain)}
        style={{ display: "block", width: "100%", textAlign: "center", padding: "12px", borderRadius: 12, border: "none", background: isPostInfidelity ? "#8A5A4E" : "#17383D", color: "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer", marginBottom: 8 }}>
        مشاهده و خریدِ جلسات
      </button>
      <a href={CONSULT_BOOKING_LINK}
        style={{ display: "block", textAlign: "center", fontSize: 11.5, color: "#5A7080", textDecoration: "underline" }}>
        یا تماسِ مستقیم با دفتر
      </a>

    </div>
  );
}

// آزمونِ آگاهی‌بخشِ بدبینی — نه پرسشنامه‌ی خودارزیابی، بلکه سنجشِ باورهایِ رایج با توضیحِ روشنگرانه
// شاخص‌هایِ ۸گانه‌یِ بدبینی — همان پرسش‌نامه‌ی جلسه‌ی اول، برایِ سنجشِ مکرر
const DISTRUST_INDICATORS = [
  "چقدر از وقتِ روزانه‌ام صرفِ نگرانی دربارهٔ وفاداریِ همسرم می‌شود؟",
  "چقدر سخت است این نگرانی‌ها را کنار بگذارم؟",
  "چقدر این نگرانی‌ها به کیفیتِ رابطه‌مان آسیب زده؟",
  "چقدر رفتارِ همسرم را محدود می‌کنم؟",
  "چقدر رفتارهایِ او را بازرسی می‌کنم؟",
  "چقدر حتی وقتی همسرم شفاف است، بازهم حسِ اطمینان نمی‌کنم؟",
  "چقدر این الگو در رابطه‌هایِ قبلی‌ام هم تکرار شده؟",
  "چقدر این نگرانی‌ها با علائمِ فیزیکی همراه است؟",
];

// پایشِ افکار — ثبتِ افکارِ منفی/مثبت/نشخوارِ فکری با ساعتِ دقیق
function ThoughtTracker({ onBack }) {
  const storageKey = "naghshe_distrust_thoughts";
  const [entries, setEntries] = useState(() => {
    try { return JSON.parse(localStorage.getItem(storageKey)) || []; } catch (e) { return []; }
  });
  const [note, setNote] = useState("");
  const [pendingType, setPendingType] = useState(null);

  function logThought(type) {
    setPendingType(type);
  }
  function confirmLog() {
    const entry = { type: pendingType, note: note.trim(), ts: Date.now() };
    const next = [entry, ...entries];
    setEntries(next);
    try { localStorage.setItem(storageKey, JSON.stringify(next)); } catch (e) {}
    setNote(""); setPendingType(null);
  }

  const today = new Date().toDateString();
  const todayEntries = entries.filter((e) => new Date(e.ts).toDateString() === today);
  const last7Days = entries.filter((e) => Date.now() - e.ts < 7 * 86400000);
  const counts = { negative: 0, positive: 0, rumination: 0 };
  last7Days.forEach((e) => { counts[e.type] = (counts[e.type] || 0) + 1; });

  // ساعاتِ پرتکرارِ افکارِ منفی — برایِ کمک به شناساییِ الگو
  const negHours = last7Days.filter((e) => e.type === "negative").map((e) => new Date(e.ts).getHours());
  const hourFreq = {};
  negHours.forEach((h) => { hourFreq[h] = (hourFreq[h] || 0) + 1; });
  const peakHour = Object.entries(hourFreq).sort((a, b) => b[1] - a[1])[0];

  const typeLabels = { negative: "😟 فکرِ منفی", positive: "😊 فکرِ مثبت", rumination: "🔄 نشخوارِ فکری" };
  const typeColors = { negative: "#A6432F", positive: "#4C8778", rumination: "#B8873A" };

  return (
    <Card>
      <h2 style={{ fontSize: 16, fontWeight: 800, color: "#1F2D3D", textAlign: "center", marginBottom: 6 }}>📝 پایشِ افکار</h2>
      <p style={{ fontSize: 11.5, color: "#5A7080", textAlign: "center", marginBottom: 16 }}>هروقت فکرِ منفی، مثبت، یا نشخوارِ فکری داشتید، همین‌جا ثبت کنید.</p>

      {pendingType ? (
        <div style={{ background: "#F7FAFC", borderRadius: 12, padding: "14px", marginBottom: 14 }}>
          <p style={{ fontSize: 12.5, fontWeight: 700, marginBottom: 8 }}>{typeLabels[pendingType]} — یادداشتِ کوتاه (اختیاری)</p>
          <textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="مثلاً: وقتی دیر جواب داد..."
            style={{ width: "100%", minHeight: 60, padding: 10, borderRadius: 8, border: "1px solid #DCE8F0", fontSize: 12.5, marginBottom: 8, boxSizing: "border-box" }} />
          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={confirmLog} style={{ flex: 1, padding: "9px", borderRadius: 10, border: "none", background: typeColors[pendingType], color: "#fff", fontWeight: 700, cursor: "pointer" }}>ثبت</button>
            <button onClick={() => { setPendingType(null); setNote(""); }} style={{ flex: 1, padding: "9px", borderRadius: 10, border: "1px solid #DCE8F0", background: "#fff", color: "#8CA3B0", cursor: "pointer" }}>انصراف</button>
          </div>
        </div>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8, marginBottom: 16 }}>
          <button onClick={() => logThought("negative")} style={{ padding: "12px 6px", borderRadius: 12, border: "1.5px solid #E8C9BC", background: "#FBEEEA", color: "#A6432F", fontWeight: 700, fontSize: 11, cursor: "pointer" }}>😟<br />منفی</button>
          <button onClick={() => logThought("positive")} style={{ padding: "12px 6px", borderRadius: 12, border: "1.5px solid #CFE6D8", background: "#F3F8F5", color: "#4C8778", fontWeight: 700, fontSize: 11, cursor: "pointer" }}>😊<br />مثبت</button>
          <button onClick={() => logThought("rumination")} style={{ padding: "12px 6px", borderRadius: 12, border: "1.5px solid #E8D8B0", background: "#FBF3E2", color: "#B8873A", fontWeight: 700, fontSize: 11, cursor: "pointer" }}>🔄<br />نشخوار</button>
        </div>
      )}

      <div style={{ background: "#FBF3E2", borderRadius: 12, padding: "12px 14px", marginBottom: 14 }}>
        <p style={{ fontSize: 12, fontWeight: 700, color: "#7A5B2E", marginBottom: 6 }}>📊 خلاصه‌ی ۷ روزِ اخیر</p>
        <p style={{ fontSize: 11.5, color: "#5A4020", margin: "0 0 3px" }}>😟 افکارِ منفی: {counts.negative} · 😊 افکارِ مثبت: {counts.positive} · 🔄 نشخوار: {counts.rumination}</p>
        {peakHour && counts.negative >= 3 && (
          <p style={{ fontSize: 11, color: "#5A4020", marginTop: 6 }}>⏰ افکارِ منفی‌تان بیشتر حوالیِ ساعتِ {peakHour[0]}:۰۰ رخ می‌دهند — شاید بدانید در آن ساعت معمولاً چه‌کار می‌کنید؟</p>
        )}
      </div>

      {todayEntries.length > 0 && (
        <>
          <p style={{ fontSize: 12, fontWeight: 700, color: "#1F2D3D", marginBottom: 8 }}>امروز</p>
          {todayEntries.map((e, i) => (
            <div key={i} style={{ background: "#F7FAFC", borderRadius: 10, padding: "8px 12px", marginBottom: 6 }}>
              <p style={{ fontSize: 11.5, fontWeight: 700, color: typeColors[e.type], margin: "0 0 2px" }}>
                {typeLabels[e.type]} · {new Date(e.ts).toLocaleTimeString("fa-IR", { hour: "2-digit", minute: "2-digit" })}
              </p>
              {e.note && <p style={{ fontSize: 11, color: "#5A7080", margin: 0 }}>{e.note}</p>}
            </div>
          ))}
        </>
      )}
      <button onClick={onBack} style={{ width: "100%", padding: "9px", borderRadius: 12, border: "none", background: "transparent", color: "#8CA3B0", cursor: "pointer", fontSize: 12, marginTop: 10 }}>
        بازگشت
      </button>
    </Card>
  );
}

// بازسنجیِ دوره‌ای — پیشنهاد می‌شود هفته‌ای دو بار برایِ دیدنِ روند
// گزارشِ یکپارچه — ترکیبِ بازسنجی، پایشِ افکار، و پیشرفتِ تکالیف در یک تصویرِ واحد
function UnifiedDistrustReport({ onBack }) {
  const assessments = (() => { try { return JSON.parse(localStorage.getItem("naghshe_distrust_assessments")) || []; } catch (e) { return []; } })();
  const thoughts = (() => { try { return JSON.parse(localStorage.getItem("naghshe_distrust_thoughts")) || []; } catch (e) { return []; } })();

  const first = assessments[assessments.length - 1];
  const last = assessments[0];
  const last7 = thoughts.filter((t) => Date.now() - t.ts < 7 * 86400000);
  const counts = { negative: 0, positive: 0, rumination: 0 };
  last7.forEach((t) => { counts[t.type] = (counts[t.type] || 0) + 1; });

  let hwDone = 0, hwTotal = 0;
  for (let num = 1; num <= 10; num++) {
    try {
      const titles = JSON.parse(localStorage.getItem(`naghshe_distrust_hw_distrust-${num}_titles`)) || [];
      const done = JSON.parse(localStorage.getItem(`naghshe_distrust_hw_distrust-${num}`)) || [];
      hwTotal += titles.length;
      hwDone += done.filter(Boolean).length;
    } catch (e) {}
  }

  const overallNarrative = (() => {
    if (!last) return "هنوز داده‌ی کافی برایِ تحلیل ندارید — با تکمیلِ اولین بازسنجی و چند روز پایشِ افکار شروع کنید.";
    let parts = [];
    if (first && assessments.length > 1) {
      const diff = last.total - first.total;
      if (diff <= -4) parts.push("از اولین سنجش تا الان، شاخصِ کلیِ بدبینی‌تان به‌طورِ محسوسی کاهش یافته — این یک پیشرفتِ واقعی است");
      else if (diff >= 4) parts.push("شاخصِ کلی نسبت به اولین سنجش بالاتر رفته — این می‌تواند به‌خاطرِ یک دوره‌ی استرس‌زا باشد، نه لزوماً بازگشتِ کامل");
      else parts.push("شاخصِ کلی نسبتاً پایدار مانده");
    }
    if (last7.length > 0) {
      if (counts.negative > counts.positive * 2) parts.push("در هفته‌ی اخیر، افکارِ منفی به‌مراتب بیشتر از افکارِ مثبت ثبت شده‌اند");
      else if (counts.positive >= counts.negative) parts.push("در هفته‌ی اخیر، توازنِ نسبتاً خوبی بینِ افکارِ مثبت و منفی داشته‌اید");
      if (counts.rumination >= 3) parts.push("نشخوارِ فکری در این هفته تکرار شده — یادآوریِ تکنیکِ «زمانِ اختصاصیِ نگرانی» (جلسه‌ی ۳) می‌تواند کمک کند");
    }
    if (hwTotal > 0) {
      const pct = Math.round((hwDone / hwTotal) * 100);
      if (pct >= 70) parts.push(`${pct}٪ از تکالیف را انجام داده‌اید — تعهدِ خوبی به مسیر دارید`);
      else if (pct > 0) parts.push(`${pct}٪ از تکالیف را انجام داده‌اید — بدونِ فشار، هروقت آماده بودید به بقیه برگردید`);
    }
    return parts.length ? parts.join("؛ ") + "." : "به مسیر ادامه دهید تا تحلیلِ دقیق‌تری ممکن شود.";
  })();

  return (
    <Card>
      <h2 style={{ fontSize: 16, fontWeight: 800, color: "#1F2D3D", textAlign: "center", marginBottom: 16 }}>🧩 گزارشِ یکپارچه‌ی مسیرِ درمان</h2>

      <div style={{ background: "#FBF3E2", borderRadius: 14, padding: "16px", marginBottom: 16 }}>
        <p style={{ fontSize: 12.5, fontWeight: 700, color: "#7A5B2E", marginBottom: 8 }}>📖 خلاصه‌ی روایی</p>
        <p style={{ fontSize: 12.5, color: "#5A4020", lineHeight: 2 }}>{overallNarrative}</p>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 16 }}>
        <div style={{ background: "#F3F8F5", borderRadius: 12, padding: "12px", textAlign: "center" }}>
          <p style={{ fontSize: 10.5, color: "#4C8778", fontWeight: 700, marginBottom: 4 }}>آخرین شاخص</p>
          <p style={{ fontSize: 20, fontWeight: 800, color: "#1F2D3D" }}>{last ? `${last.total}/۳۲` : "—"}</p>
        </div>
        <div style={{ background: "#F7FAFC", borderRadius: 12, padding: "12px", textAlign: "center" }}>
          <p style={{ fontSize: 10.5, color: "#5A7080", fontWeight: 700, marginBottom: 4 }}>تعدادِ سنجش‌ها</p>
          <p style={{ fontSize: 20, fontWeight: 800, color: "#1F2D3D" }}>{assessments.length}</p>
        </div>
        <div style={{ background: "#FBEEEA", borderRadius: 12, padding: "12px", textAlign: "center" }}>
          <p style={{ fontSize: 10.5, color: "#A6432F", fontWeight: 700, marginBottom: 4 }}>افکارِ منفی (هفته)</p>
          <p style={{ fontSize: 20, fontWeight: 800, color: "#1F2D3D" }}>{counts.negative}</p>
        </div>
        <div style={{ background: "#F3F8F5", borderRadius: 12, padding: "12px", textAlign: "center" }}>
          <p style={{ fontSize: 10.5, color: "#4C8778", fontWeight: 700, marginBottom: 4 }}>افکارِ مثبت (هفته)</p>
          <p style={{ fontSize: 20, fontWeight: 800, color: "#1F2D3D" }}>{counts.positive}</p>
        </div>
      </div>

      <div style={{ marginBottom: 16 }}>
        <p style={{ fontSize: 12, fontWeight: 700, color: "#1F2D3D", marginBottom: 6 }}>📚 پیشرفتِ تکالیف</p>
        <div style={{ height: 10, background: "#EDF2F5", borderRadius: 999, overflow: "hidden" }}>
          <div style={{ height: "100%", width: `${hwTotal ? (hwDone / hwTotal) * 100 : 0}%`, background: "#9C6B2F", borderRadius: 999 }} />
        </div>
        <p style={{ fontSize: 11, color: "#8CA3B0", marginTop: 4 }}>{hwDone} از {hwTotal} تکلیف انجام شده</p>
      </div>

      {counts.rumination >= 3 && (
        <div style={{ background: "#FBF3E2", border: "1px solid #E8D8B0", borderRadius: 12, padding: "12px 14px", marginBottom: 16 }}>
          <p style={{ fontSize: 11.5, color: "#7A5B2E", lineHeight: 1.9 }}>
            🔄 نشخوارِ فکری‌تان در این هفته {counts.rumination} بار ثبت شده. جلسه‌ی ۳ (فنِ «زمانِ اختصاصیِ نگرانی») را دوباره مرور کنید.
          </p>
        </div>
      )}

      <button onClick={onBack} style={{ width: "100%", padding: "9px", borderRadius: 12, border: "none", background: "transparent", color: "#8CA3B0", cursor: "pointer", fontSize: 12 }}>
        بازگشت
      </button>
    </Card>
  );
}

// گزارشِ یکپارچه‌یِ عمومی — برایِ همه‌یِ بسته‌ها (تکالیف + رونـدِ خلق)
function UnifiedProgressReport({ pkgKey, onBack }) {
  const total = TREATMENT_PACKAGES[pkgKey].sessions;
  let hwDone = 0, hwTotal = 0;
  const moodPairs = [];
  for (let num = 1; num <= total; num++) {
    const sid = `${pkgKey}-${num}`;
    try {
      const titles = JSON.parse(localStorage.getItem(`naghshe_distrust_hw_${sid}_titles`)) || [];
      const done = JSON.parse(localStorage.getItem(`naghshe_distrust_hw_${sid}`)) || [];
      hwTotal += titles.length;
      hwDone += done.filter(Boolean).length;
    } catch (e) {}
    try {
      const beforeRaw = localStorage.getItem(`mood_before_${sid}`);
      const afterRaw = localStorage.getItem(`mood_after_${sid}`);
      const before = beforeRaw ? (JSON.parse(beforeRaw)?.value ?? beforeRaw) : null;
      const after = afterRaw ? (JSON.parse(afterRaw)?.value ?? afterRaw) : null;
      if (before !== null && after !== null) moodPairs.push({ num, before: Number(before), after: Number(after) });
    } catch (e) {}
  }

  const avgBefore = moodPairs.length ? (moodPairs.reduce((a, b) => a + b.before, 0) / moodPairs.length) : null;
  const avgAfter = moodPairs.length ? (moodPairs.reduce((a, b) => a + b.after, 0) / moodPairs.length) : null;

  const narrative = (() => {
    const parts = [];
    if (hwTotal > 0) {
      const pct = Math.round((hwDone / hwTotal) * 100);
      parts.push(pct >= 70 ? `${pct}٪ از تکالیف را انجام داده‌اید — تعهدِ خوبی به مسیر دارید` : `${pct}٪ از تکالیف را انجام داده‌اید`);
    }
    if (avgBefore !== null && avgAfter !== null) {
      const diff = avgAfter - avgBefore;
      if (diff >= 1) parts.push("به‌طورِ میانگین، خلقتان بعدِ هر جلسه نسبت به قبلش بهتر شده — نشانه‌ی خوبی از تاثیرِ جلسات");
      else if (diff <= -1) parts.push("خلقتان بعدِ جلسات گاهی افت کرده — این طبیعی است، به‌خصوص جلساتی که موضوعاتِ سخت را باز می‌کنند");
      else parts.push("خلقتان قبل و بعدِ جلسات نسبتاً پایدار بوده");
    }
    return parts.length ? parts.join("؛ ") + "." : "با پیشرفت در جلسات و تکمیلِ تکالیف، این گزارش کامل‌تر می‌شود.";
  })();

  return (
    <Card>
      <h2 style={{ fontSize: 16, fontWeight: 800, color: "#1F2D3D", textAlign: "center", marginBottom: 16 }}>🧩 گزارشِ یکپارچه‌ی مسیرِ درمان</h2>
      <div style={{ background: "#F3F8F5", borderRadius: 14, padding: "16px", marginBottom: 16 }}>
        <p style={{ fontSize: 12.5, fontWeight: 700, color: "#4C8778", marginBottom: 8 }}>📖 خلاصه‌ی روایی</p>
        <p style={{ fontSize: 12.5, color: "#3A4A52", lineHeight: 2 }}>{narrative}</p>
      </div>
      <div style={{ marginBottom: 16 }}>
        <p style={{ fontSize: 12, fontWeight: 700, color: "#1F2D3D", marginBottom: 6 }}>📚 پیشرفتِ تکالیف</p>
        <div style={{ height: 10, background: "#EDF2F5", borderRadius: 999, overflow: "hidden" }}>
          <div style={{ height: "100%", width: `${hwTotal ? (hwDone / hwTotal) * 100 : 0}%`, background: "#17383D", borderRadius: 999 }} />
        </div>
        <p style={{ fontSize: 11, color: "#8CA3B0", marginTop: 4 }}>{hwDone} از {hwTotal} تکلیف انجام شده</p>
      </div>
      {avgBefore !== null && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 10 }}>
          <div style={{ background: "#FBF3E2", borderRadius: 12, padding: "12px", textAlign: "center" }}>
            <p style={{ fontSize: 10.5, color: "#9C6B2F", fontWeight: 700, marginBottom: 4 }}>میانگینِ خلق قبل</p>
            <p style={{ fontSize: 20, fontWeight: 800, color: "#1F2D3D" }}>{avgBefore.toFixed(1)}/۱۰</p>
          </div>
          <div style={{ background: "#F3F8F5", borderRadius: 12, padding: "12px", textAlign: "center" }}>
            <p style={{ fontSize: 10.5, color: "#4C8778", fontWeight: 700, marginBottom: 4 }}>میانگینِ خلق بعد</p>
            <p style={{ fontSize: 20, fontWeight: 800, color: "#1F2D3D" }}>{avgAfter.toFixed(1)}/۱۰</p>
          </div>
        </div>
      )}
      <button onClick={onBack} style={{ width: "100%", padding: "9px", borderRadius: 12, border: "none", background: "transparent", color: "#8CA3B0", cursor: "pointer", fontSize: 12, marginTop: 8 }}>
        بازگشت
      </button>
    </Card>
  );
}

// راهنمایِ کوتاه برایِ همسر — یک منبعِ مستقل، نه جلسه‌ای که باید «گذرانده» شود
// ========== ماژولِ سرگرمی — یادگیریِ خودآگاهی از طریقِ بازی ==========

