// کتابخانه‌ی تکنیک‌ها، دسترسیِ سریع — ۱۲۴ موضوع، ۵ تکنیکِ فوری برایِ هرکدام
function QuickTechniqueLibrary({ onBack }) {
  const [query, setQuery] = useState("");
  const [openTopic, setOpenTopic] = useState(null);
  const [openCategory, setOpenCategory] = useState(null);

  const matchesQuery = (key) => {
    if (!query.trim()) return true;
    const q = query.trim().toLowerCase();
    const topic = QUICK_TECHNIQUE_TOPICS[key];
    if (topic.label.toLowerCase().includes(q)) return true;
    return topic.techniques.some((t) => t.name.toLowerCase().includes(q) || t.howTo.toLowerCase().includes(q));
  };

  if (openTopic) {
    const topic = QUICK_TECHNIQUE_TOPICS[openTopic];
    return (
      <Card>
        <button onClick={() => setOpenTopic(null)} style={{ border: "none", background: "none", color: "#17383D", fontSize: 12, cursor: "pointer", marginBottom: 10 }}>‹ بازگشت به فهرست</button>
        <h2 style={{ fontSize: 16, fontWeight: 800, color: "#1F2D3D", textAlign: "center", marginBottom: 16 }}>{topic.label}</h2>
        {topic.techniques.map((t, i) => (
          <div key={i} style={{ background: "#F7FAFC", border: "1px solid #DCE8F0", borderRadius: 12, padding: "12px 14px", marginBottom: 8 }}>
            <p style={{ fontSize: 13, fontWeight: 700, color: "#17383D", margin: "0 0 5px" }}>{i + 1}. {t.name}</p>
            <p style={{ fontSize: 12, color: "#3A4A52", lineHeight: 1.9, margin: 0 }}>{t.howTo}</p>
          </div>
        ))}
        <button onClick={onBack} style={{ width: "100%", padding: "9px", borderRadius: 12, border: "none", background: "transparent", color: "#8CA3B0", cursor: "pointer", fontSize: 12, marginTop: 10 }}>بازگشت به صفحه‌ی اصلی</button>
      </Card>
    );
  }

  return (
    <Card>
      <h2 style={{ fontSize: 17, fontWeight: 800, color: "#1F2D3D", textAlign: "center", marginBottom: 6 }}>🧰 کتابخانه‌ی تکنیک‌ها</h2>
      <p style={{ fontSize: 12, color: "#5A7080", textAlign: "center", marginBottom: 16 }}>۱۲۴ موضوع، ۵ تکنیکِ فوری برایِ هرکدام — دسترسیِ سریع</p>
      <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="جست‌وجو (مثلاً «اضطراب» یا «خواب»)"
        style={{ width: "100%", padding: "12px", borderRadius: 10, border: "1px solid #DCE8F0", marginBottom: 16, fontSize: 13, boxSizing: "border-box" }} />

      {query.trim() ? (
        Object.keys(QUICK_TECHNIQUE_TOPICS).filter(matchesQuery).length === 0 ? (
          <p style={{ textAlign: "center", fontSize: 12, color: "#8CA3B0" }}>چیزی برایِ «{query}» پیدا نشد.</p>
        ) : (
          Object.keys(QUICK_TECHNIQUE_TOPICS).filter(matchesQuery).map((key) => (
            <button key={key} onClick={() => setOpenTopic(key)}
              style={{ width: "100%", textAlign: "right", padding: "12px 14px", borderRadius: 10, border: "1px solid #DCE8F0", background: "#fff", marginBottom: 6, cursor: "pointer", fontSize: 13, color: "#1F2D3D" }}>
              {QUICK_TECHNIQUE_TOPICS[key].label}
            </button>
          ))
        )
      ) : (
        Object.entries(QUICK_TECHNIQUE_CATEGORIES).map(([cat, keys]) => (
          <div key={cat} style={{ marginBottom: 8 }}>
            <button onClick={() => setOpenCategory(openCategory === cat ? null : cat)}
              style={{ width: "100%", textAlign: "right", padding: "12px 14px", borderRadius: 10, border: "1px solid #E8D8B0", background: "#FBF3E2", color: "#7A5B2E", fontWeight: 700, fontSize: 13, cursor: "pointer" }}>
              {openCategory === cat ? "▲ " : "▼ "}{cat} ({keys.length})
            </button>
            {openCategory === cat && (
              <div style={{ marginTop: 6 }}>
                {keys.map((key) => (
                  <button key={key} onClick={() => setOpenTopic(key)}
                    style={{ width: "100%", textAlign: "right", padding: "10px 14px", borderRadius: 8, border: "1px solid #F0E6D8", background: "#fff", marginBottom: 4, cursor: "pointer", fontSize: 12.5, color: "#3A4A52" }}>
                    {QUICK_TECHNIQUE_TOPICS[key].label}
                  </button>
                ))}
              </div>
            )}
          </div>
        ))
      )}
      <button onClick={onBack} style={{ width: "100%", padding: "9px", borderRadius: 12, border: "none", background: "transparent", color: "#8CA3B0", cursor: "pointer", fontSize: 12, marginTop: 10 }}>بازگشت</button>
    </Card>
  );
}

